INSERT INTO "miner_fundamentals" (
  "symbol", "name", "primary_metal", "jurisdiction", "project_stage", "production_oz", "aisc_usd_per_oz", "resource_moz", "reserve_moz", "cash_aud", "debt_aud", "market_cap_aud", "npv_aud", "capex_aud", "irr_percent", "jurisdiction_score", "balance_sheet_score", "dilution_score", "management_score", "notes", "source_url", "as_of_date", "updated_at"
) VALUES
  ('ATOM', 'Global X Uranium ETF', 'Uranium / nuclear fuel-cycle ETF', 'Global', 'ETF', NULL, NULL, NULL, NULL, NULL, NULL, 135000000, NULL, NULL, NULL, 4, 3, 4, 4, 'ETF record: mine-level production, AISC, resources and reserves do not apply. Market cap field is used as AUM; Global X reported AUM above A$135M and top holdings led by Cameco, Sprott Physical Uranium Trust, NexGen, Oklo and Uranium Energy. Scores reflect diversified uranium/nuclear-cycle exposure rather than a single issuer.', 'https://www.globalxetfs.com.au/funds/atom/', '2026-08-21'::date, NOW()),
  ('B', 'Barrick Mining Corporation', 'Gold / copper', 'Global; 17 countries', 'Producer', 3075000, 1866, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4, 5, 4, 4, 'Production field is the midpoint of unchanged 2026 gold guidance, while AISC is Q2 2026 gold AISC. Cash, debt and reserve/resource fields are left blank pending direct capture from the quarterly financial statements and latest reserve tables. Current watch items are Nevada Gold Mines restructuring, planned North American IPO and multi-jurisdiction execution.', 'https://www.barrick.com/English/news/news-details/2026/q2-2026-results/default.aspx', '2026-06-30'::date, NOW()),
  ('DML', 'Denison Mines Corp.', 'Uranium', 'Canada', 'Developer / construction', NULL, 6.28, 56.3, 56.7, NULL, NULL, NULL, 1596690000, 610200000, 73, 5, 3, 2, 4, 'Wheeler River/Phoenix values use uranium lb units despite the app label saying Moz/oz. Resource field uses Phoenix measured and indicated U3O8; reserve field uses Phoenix proven and probable U3O8. NPV and capex are 2026 Phoenix update figures converted from Canadian dollars at about C$1=A$1.017. AISC field uses the Phoenix FS estimated all-in cost per lb U3O8, not gold/silver oz.', 'https://denisonmines.com/projects/wheeler-river-project/phoenix/', '2026-06-30'::date, NOW()),
  ('EDR', 'Endeavour Silver Corp.', 'Silver / gold / base metals', 'Mexico, Peru, United States', 'Producer / development ramp', 1943955, 36.89, NULL, NULL, 331240000, NULL, NULL, NULL, NULL, NULL, 3, 4, 3, 3, 'Q2 2026 silver production, consolidated AISC and cash are company-reported. Production is the latest reported quarter, not annualized; cash is converted at about US$1=A$1.40. Reserve/resource and debt fields are left blank pending direct capture from annual tables. Main risks are Terronera ramp-up, Kolpa integration, Pitarrilla study work and Mexico/Peru operating exposure.', 'https://www.sec.gov/Archives/edgar/data/1277866/000117184326005027/exh_991.htm', '2026-06-30'::date, NOW()),
  ('EU', 'enCore Energy Corp.', 'Uranium', 'United States', 'Producer / ISR ramp', 131274, 57.36, NULL, NULL, 30520000, NULL, NULL, NULL, NULL, NULL, 5, 3, 3, 3, 'Production field uses H1 2026 U3O8 extraction pounds and cost field uses H1 2026 extraction cost per lb, not gold/silver AISC. Cash is unrestricted cash converted at about US$1=A$1.40; total liquidity was materially higher because it included marketable securities and inventory. Key risks are Alta Mesa permit timing, low near-term extraction volumes and reliance on purchased material for deliveries.', 'https://encore.mediaroom.com/2026-08-13-enCore-Energy-Reports-Q2-2026-Financial-Results', '2026-06-30'::date, NOW()),
  ('GGP', 'Greatland Resources Limited', 'Gold / copper', 'Australia', 'Producer / Havieron development', 328987, 1556.43, NULL, 1.8, 1289000000, 0, NULL, NULL, 1065000000, NULL, 5, 5, 4, 4, 'FY2026 production, AISC, closing cash and no-debt status are company-reported. AISC was reported in A$/oz and converted to US$/oz at about US$1=A$1.40 for the app field. Reserve field captures the June 2026 Telfer Ore Reserve estimate noted in the quarterly report; capex is Havieron pre-production capital. Key watch item is converting Telfer cash generation into lower-risk Havieron execution.', 'https://www.investegate.co.uk/announcement/rns/greatland-gold--ggp/june-2026-quarterly-activities-report-/9692219', '2026-06-30'::date, NOW()),
  ('HSTR', 'Heliostar Metals Ltd.', 'Gold / silver', 'Mexico, United States', 'Producer / growth', 52500, 2287, 0.975, NULL, 60265800, 0, NULL, NULL, NULL, NULL, 3, 4, 3, 3, 'Production field is midpoint of unchanged 2026 gold guidance; AISC is Q2 2026 corporate AISC per gold ounce sold. Cash is Q2 2026 cash converted at about US$1=A$1.40 and debt is set to zero based on company commentary. Resource field captures Goldstrike indicated ounces only, not a full company resource inventory. Key risks are Mexico operating exposure, Goldstrike integration and sustaining the San Agustin/La Colorada ramp.', 'https://www.heliostarmetals.com/news-media/news-releases/heliostar-presents-q2-2026-financial-and-operating-results-with-record-gold-production-and-cash-balance', '2026-06-30'::date, NOW()),
  ('LAM', 'Laramide Resources Ltd.', 'Uranium', 'Australia, United States', 'Developer / explorer', 4900000, 32.4, 65.8, NULL, NULL, NULL, NULL, 1058700000, 756000000, 33, 4, 2, 2, 3, 'Westmoreland values use uranium lb units despite the app label saying Moz/oz. Production is planned average annual U3O8 output from years 2-10, cost is PEA C1 operating cost per lb, resource combines indicated and inferred U3O8, and no reserve has been declared. NPV is the company-reported post-tax A$ NPV7.5; capex converts US$456M initial plus US$84M contingency at about US$1=A$1.40. Main risks are PEA-stage confidence, Queensland uranium policy and funding/dilution.', 'https://laramide.com/laramide-resources-announces-updated-preliminary-e-15357/', '2026-07-22'::date, NOW()),
  ('NUKZ', 'Range Nuclear Renaissance Index ETF', 'Nuclear energy ETF', 'Global', 'ETF', NULL, NULL, NULL, NULL, NULL, NULL, 1126103304, NULL, NULL, NULL, 4, 3, 4, 4, 'ETF record: mine-level economics do not apply. Market cap field is used as AUM, converted from US$804.4M at about US$1=A$1.40. Top exposures include Cameco plus nuclear utilities, engineering and reactor/fuel-chain names such as GE Vernova, Rolls-Royce, Endesa, CEZ and Samsung C&T. Scores reflect thematic concentration and diversified issuer exposure.', 'https://www.rangeetfs.com/nukz?trk=public_post-text', '2026-08-20'::date, NOW()),
  ('SCZ', 'Santacruz Silver Mining Ltd.', 'Silver / zinc / lead / copper', 'Bolivia, Mexico', 'Producer', 1573100, NULL, NULL, NULL, 70557200, NULL, NULL, NULL, NULL, NULL, 2, 4, 3, 3, 'Q2 2026 silver production and cash are company-reported; production is the latest reported quarter, not annualized, and cash is converted at about US$1=A$1.40. AISC, reserve/resource and debt fields remain blank until the latest technical and balance-sheet tables are captured directly. Key risks are Bolivia operating/political exposure, multi-metal price mix, note refinancing and recent safety incident history.', 'https://www.nasdaq.com/press-release/santacruz-silver-reports-second-quarter-2026-financial-results-2026-08-17', '2026-06-30'::date, NOW()),
  ('SLVM', 'Global X Silver Miners ETF', 'Silver miners ETF', 'Global', 'ETF', NULL, NULL, NULL, NULL, NULL, NULL, 85000000, NULL, NULL, NULL, 3, 3, 4, 4, 'ETF record: mine-level economics do not apply. Market cap field is used as AUM because Global X reports the fund above A$85M. Top holdings were led by Wheaton Precious Metals, Pan American Silver, Coeur, Hecla and First Majestic. Scores reflect diversified silver-miner exposure with unhedged currency and single-theme beta.', 'https://www.globalxetfs.com.au/funds/slvm/', '2026-08-20'::date, NOW()),
  ('U', 'Sprott Physical Uranium Trust', 'Physical uranium', 'Canada / global uranium storage', 'Physical uranium trust', NULL, NULL, NULL, NULL, NULL, NULL, 10156190502, NULL, NULL, NULL, 4, 5, 5, 4, 'Physical trust record, likely the app/broker alias for the TSX U.U USD unit; mine production, AISC, resources and reserves do not apply at issuer level. Market cap field is used as total net asset value, converted from US$7.254B at about US$1=A$1.40. Sprott reported 81.697M lb U3O8 held. Main risks are uranium spot-price beta, premium/discount movement and trust liquidity.', 'https://sprott.com/investment-strategies/exchange-listed-products/physical-commodity-funds/uranium/', '2026-08-17'::date, NOW()),
  ('U.UN', 'Sprott Physical Uranium Trust', 'Physical uranium', 'Canada / global uranium storage', 'Physical uranium trust', NULL, NULL, NULL, NULL, NULL, NULL, 10156190502, NULL, NULL, NULL, 4, 5, 5, 4, 'Physical trust record for the TSX U.UN CAD unit; mine production, AISC, resources and reserves do not apply at issuer level. Market cap field is used as total net asset value, converted from US$7.254B at about US$1=A$1.40. Sprott reported 81.697M lb U3O8 held. Main risks are uranium spot-price beta, premium/discount movement and trust liquidity.', 'https://sprott.com/investment-strategies/exchange-listed-products/physical-commodity-funds/uranium/', '2026-08-17'::date, NOW()),
  ('URA', 'Global X Uranium ETF', 'Uranium / nuclear fuel-cycle ETF', 'Global', 'ETF', NULL, NULL, NULL, NULL, NULL, NULL, 7560000000, NULL, NULL, NULL, 3, 3, 4, 4, 'ETF record: mine-level economics do not apply. Market cap field is used as AUM, converted from a reported US$5.4B at about US$1=A$1.40. Top exposures include Cameco, Sprott Physical Uranium Trust, Oklo, NexGen, Uranium Energy, Kazatomprom and Energy Fuels. Scores reflect diversified uranium/nuclear-cycle exposure but high uranium-cycle concentration.', 'https://www.globalxetfs.com/funds/ura/', '2026-08-11'::date, NOW())
